{"command":"python3 -c "
# Check for times beyond 24:00:00
import csv
with open('inputs/gtfs/extracted/stop_times.txt', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        for col in ['arrival_time', 'departure_time']:
            t = row[col]
            if t:
                parts = t.split(':')
                if len(parts) == 3:
                    try:
                        h = int(parts[0])
                        if h >= 24:
                            print(f'Extended time found: {col}={t} in row {row}')
                    except:
                        pass
""}

